namespace OpenAntiLag {
 public sealed class FakeNetworkStore:INetworkStateStore {
  public NetworkState Value=new NetworkState();public bool Fail;
  public NetworkState Load(){return Copy(Value);}public void Save(NetworkState value){if(Fail)throw new IOException("Journal full");NetworkValidation.State(value);Value=Copy(value);}
  static NetworkState Copy(NetworkState value){using(var s=new MemoryStream()){var x=new XmlSerializer(typeof(NetworkState));x.Serialize(s,value);s.Position=0;return (NetworkState)x.Deserialize(s);}}
 }
 public sealed class FakeNetworkHost:INetworkConfigurationHost {
  public readonly Dictionary<string,DnsConfig> Dns=new Dictionary<string,DnsConfig>();public readonly Dictionary<string,QosPolicy> Qos=new Dictionary<string,QosPolicy>();public bool Block,Silent,ThrowAfter,FailRestore,Partial;public int Writes;
  public void Preflight(string feature){if(Block)throw new UnauthorizedAccessException("No admin / feature unavailable");}
  public DnsConfig ReadDns(string id,int family){return Dns[id+":"+family].Copy();}
  public void WriteDns(DnsConfig value){Writes++;if(FailRestore){FailRestore=false;throw new IOException("Restore failure");}if(!Silent)Dns[value.Adapter+":"+value.Family]=Partial?new DnsConfig {Adapter=value.Adapter,Family=value.Family,Servers=new[]{value.Family==4?"9.9.9.9":"2620:fe::fe"}}:value.Copy();if(ThrowAfter){ThrowAfter=false;throw new IOException("Interrupted DNS write");}}
  public QosPolicy ReadQos(string name){QosPolicy value;return Qos.TryGetValue(name,out value)?value:null;}
  public void CreateQos(QosPolicy value){Writes++;if(!Silent){value.Fingerprint="Original policy attributes";Qos[value.Name]=value;}if(ThrowAfter){ThrowAfter=false;throw new IOException("Interrupted QoS");}}
  public void DeleteQos(string name){Writes++;if(FailRestore){FailRestore=false;throw new IOException("Restore failure");}Qos.Remove(name);}
 }
 public sealed class FakeProbeTransport:IProbeTransport {
  public int Calls;public bool Fail,CancelDuring;public CancellationTokenSource Source;
  public Task<ProbeSample> Ping(IPAddress address,int timeout,CancellationToken ct){Calls++;if(CancelDuring&&Source!=null)Source.Cancel();ct.ThrowIfCancellationRequested();return Task.FromResult(new ProbeSample {Address=address.ToString(),Sent=true,Success=!Fail,Milliseconds=12,Detail=Fail?"TimedOut":"Success"});}
  public Task<ProbeSample> Tcp(IPAddress address,int port,int timeout,CancellationToken ct){return Task.FromResult(new ProbeSample {Address=address.ToString(),Kind="TCP connect",Sent=true,Success=true,Detail="Connected",Milliseconds=10});}
 }
 public sealed class FakeNextHandler:HttpMessageHandler {
  public HttpStatusCode Code=HttpStatusCode.OK;public string Body="{\"data\":[]}";public bool Unavailable;public string SeenKey,SeenUri,SeenBody;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){if(Unavailable)throw new HttpRequestException("offline");SeenKey=request.Headers.GetValues("X-Api-Key").Single();SeenUri=request.RequestUri.ToString();SeenBody=request.Content==null?null:await request.Content.ReadAsStringAsync();return new HttpResponseMessage(Code){Content=new StringContent(Body)};}
 }
 public static class NetworkTests {
  static int count;static void Assert(bool value,string message="Network assertion failed"){if(!value)throw new Exception(message);}static void Throws(Action action){bool failed=false;try{action();}catch{failed=true;}Assert(failed,"Expected failure");}static void Test(string name,Action action){action();count++;Console.WriteLine("PASS "+name);}
  static readonly string Id="{55555555-5555-5555-5555-555555555555}";
  static DnsConfig Config(int family,bool automatic=false){return new DnsConfig {Adapter=Id,Family=family,Automatic=automatic,Servers=automatic?new string[0]:new[]{family==4?"1.1.1.1":"2606:4700:4700::1111"}};}
  static FakeNetworkHost Host(int family,bool automatic){var h=new FakeNetworkHost();var original=Config(family,automatic);if(!automatic)original.Servers=new[]{family==4?"8.8.8.8":"2001:4860:4860::8888"};h.Dns[Id+":"+family]=original;return h;}
  static QosPolicy Policy(){return new QosPolicy {Name="OpenAntiLag-"+Guid.NewGuid().ToString("N"),Path=@"C:\Games\Background.exe",BitsPerSecond=2000000,Dscp=0};}
  static ProbeSample Sample(double value,bool ok=true,string kind="ICMP"){return new ProbeSample {Sent=true,Success=ok,Milliseconds=value,Kind=kind,InterfaceId="same",Address="1.1.1.1"};}
  static void Temp(Action<string> action){string path=Path.Combine(Path.GetTempPath(),"OpenAntiLag-net-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);try{action(path);}finally{Directory.Delete(path,true);}}
  public static int Run(){
   Test("Network RTT mean, median, interpolated P95, jitter and population deviation",delegate{var s=ProbeSummary.Calculate(new[]{Sample(10),Sample(20),Sample(30),Sample(40)});Assert(s.Sent==4&&s.Lost==0&&s.Mean==25&&s.Median==25&&s.P95==38.5&&s.Jitter==10&&Math.Abs(s.StandardDeviation.Value-Math.Sqrt(125))<.001);});
   Test("Network loss excludes TCP, DNS and unsent cancellations",delegate{var cancelled=Sample(0,false);cancelled.Sent=false;var s=ProbeSummary.Calculate(new[]{Sample(10),Sample(0,false),Sample(4,true,"TCP connect"),Sample(4,true,"DNS"),cancelled});Assert(s.Sent==2&&s.Lost==1&&s.LossPercent==50);});
   Test("Network jitter does not bridge failed probes or interface changes",delegate{var change=Sample(50);change.InterfaceId="changed";var s=ProbeSummary.Calculate(new[]{Sample(10),Sample(0,false),Sample(90),change});Assert(!s.Jitter.HasValue);});
   Test("Network empty and all failed histories have no fabricated RTT",delegate{var empty=ProbeSummary.Calculate(new ProbeSample[0]);var failed=ProbeSummary.Calculate(new[]{Sample(0,false)});Assert(!empty.Mean.HasValue&&!failed.P95.HasValue&&failed.LossPercent==100);});
   Test("Network inputs reject URLs, commands and malformed DNS addresses",delegate{foreach(string host in new[]{"https://server/path","host:27015","a;whoami","","-bad.test"})Throws(()=>NetworkInput.Host(host));Assert(NetworkInput.Host("EXAMPLE.COM.")=="example.com");Throws(()=>NetworkInput.Servers("1.1.1.1",6));Throws(()=>NetworkInput.Servers("1.1.1.1,1.1.1.1",4));});
   Test("Network timeout and cancellation complete without waiting for abandoned task",delegate{var never=new TaskCompletionSource<int>();Throws(()=>NetworkInput.Bounded(never.Task,10,CancellationToken.None).GetAwaiter().GetResult());using(var ct=new CancellationTokenSource()){ct.Cancel();Throws(()=>NetworkInput.Bounded(never.Task,1000,ct.Token).GetAwaiter().GetResult());}});
   Test("Network cancellation cannot append a false lost probe",delegate{using(var ct=new CancellationTokenSource()){var transport=new FakeProbeTransport {CancelDuring=true,Source=ct};var m=new NetworkMonitor(transport,()=>new AdapterSnapshot[0]);Throws(()=>m.Run(new MonitorOptions {Host="127.0.0.1",DurationSeconds=5},ct.Token).GetAwaiter().GetResult());Assert(m.History.Snapshot().Length==0);}});
   Test("Network no-interface and TCP fallback remain separate observations",delegate{using(var ct=new CancellationTokenSource()){var t=new FakeProbeTransport {Fail=true};var m=new NetworkMonitor(t,()=>new AdapterSnapshot[0]);bool offline=false;m.Notice+=s=>{if(s.Contains("нет работающего"))offline=true;};m.Sample+=s=>{if(s.Kind=="TCP connect")ct.Cancel();};Throws(()=>m.Run(new MonitorOptions {Host="127.0.0.1",DurationSeconds=5,TcpFallback=true},ct.Token).GetAwaiter().GetResult());Assert(offline&&m.History.Snapshot().Any(s=>s.Kind=="TCP connect")&&ProbeSummary.Calculate(m.History.Snapshot()).Sent==1);}});
   Test("Interface signature detects link/address changes without assuming a game route",delegate{var a=new AdapterSnapshot {Id="a",State="Up",Addresses=new[]{"1.2.3.4"}};string s=NetworkAdapters.Signature(new[]{a});a.State="Down";Assert(s!=NetworkAdapters.Signature(new[]{a}));});
   Test("Network history is bounded and CSV blocks spreadsheet formula injection",delegate{var h=new ObservationHistory();for(int i=0;i<11000;i++)h.Add(Sample(i));Assert(h.Snapshot().Length==10000);Assert(ObservationHistory.CsvCell("=cmd").StartsWith("\"'="));});
   Test("Network monitor refuses aggressive frequency and unbounded sessions",delegate{Throws(()=>new MonitorOptions {Host="1.1.1.1",IntervalMs=1}.Validate());Throws(()=>new MonitorOptions {Host="1.1.1.1",DurationSeconds=99999}.Validate());Throws(()=>new MonitorOptions {Host="1.1.1.1",DurationSeconds=5,IntervalMs=60000}.Validate());});
   foreach(int family in new[]{4,6})foreach(bool dhcp in new[]{true,false}){int f=family;bool auto=dhcp;Test("DNS exact restore IPv"+f+" "+(auto?"DHCP":"static")+" after restart",delegate{var h=Host(f,auto);var original=h.ReadDns(Id,f);var store=new FakeNetworkStore();new NetworkController(h,store,"owner").ApplyDns(Config(f));Assert(store.Value.Dns.Count==1);new NetworkController(h,store,"owner").Restore("DNS");Assert(h.ReadDns(Id,f).Same(original)&&store.Value.Dns.Count==0);});}
   Test("DNS journal failure and unavailable rights perform no system writes",delegate{var h=Host(4,true);var store=new FakeNetworkStore {Fail=true};Throws(()=>new NetworkController(h,store,"owner").ApplyDns(Config(4)));Assert(h.Writes==0);store.Fail=false;h.Block=true;Throws(()=>new NetworkController(h,store,"owner").ApplyDns(Config(4)));Assert(h.Writes==0);});
   Test("DNS write exception rolls back original mode",delegate{var h=Host(4,true);h.ThrowAfter=true;var s=new FakeNetworkStore();Throws(()=>new NetworkController(h,s,"owner").ApplyDns(Config(4)));Assert(h.ReadDns(Id,4).Automatic&&s.Value.Dns.Count==0);});
   Test("DNS silent rejection is not reported as success",delegate{var h=Host(6,true);h.Silent=true;Throws(()=>new NetworkController(h,new FakeNetworkStore(),"owner").ApplyDns(Config(6)));Assert(h.ReadDns(Id,6).Automatic);});
   Test("DNS external changes are preserved and recovery journal retained",delegate{var h=Host(4,true);var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");c.ApplyDns(Config(4));h.Dns[Id+":4"]=new DnsConfig {Adapter=Id,Family=4,Servers=new[]{"9.9.9.9"}};Throws(()=>c.Restore("DNS"));Assert(h.ReadDns(Id,4).Servers[0]=="9.9.9.9"&&s.Value.Dns.Count==1);});
   Test("DNS partial unknown write never overwrites an external-looking result",delegate{var h=Host(4,true);h.Partial=true;var s=new FakeNetworkStore();Throws(()=>new NetworkController(h,s,"owner").ApplyDns(Config(4)));Assert(h.ReadDns(Id,4).Servers[0]=="9.9.9.9"&&s.Value.Dns.Count==1);});
   Test("DNS restore can be retried after partial failure",delegate{var h=Host(4,true);var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");c.ApplyDns(Config(4));h.FailRestore=true;Throws(()=>c.Restore("DNS"));Assert(s.Value.Dns.Count==1);new NetworkController(h,s,"owner").Restore("DNS");Assert(h.ReadDns(Id,4).Automatic&&s.Value.Dns.Count==0);});
   Test("DNS repeated apply cannot replace backup",delegate{var h=Host(4,true);var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");c.ApplyDns(Config(4));Throws(()=>c.ApplyDns(Config(4)));Assert(s.Value.Dns[0].Original.Automatic);});
   Test("QoS CIM byte rate is converted to command bit rate exactly once",delegate{var p=Policy();string json=new JavaScriptSerializer().Serialize(new QosNativeSnapshot {Name=p.Name,Path=p.Path,BytesPerSecond=250000,Dscp=-1,Fingerprint="x"});Assert(WindowsNetworkHost.DecodeQos(json).BitsPerSecond==2000000);Assert(WindowsNetworkHost.DecodeQos("null")==null);});
   Test("QoS apply readback and restore remove only owned policy",delegate{var h=new FakeNetworkHost();var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");var p=Policy();c.ApplyQos(p);Assert(h.Qos.Count==1);new NetworkController(h,s,"owner").Restore("QoS");Assert(h.Qos.Count==0&&s.Value.Qos.Count==0);});
   Test("QoS cannot target Windows, anti-cheat or invalid executable patterns",delegate{foreach(string path in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"system32","svchost.exe"),@"C:\Games\FACEITService.exe",@"C:\Games\EasyAntiCheat.exe",@"C:\Program Files\EasyAntiCheat_EOS\launcher.exe",@"*.exe","chrome.exe"}){var p=Policy();p.Path=path;Throws(()=>NetworkValidation.Qos(p));}});
   Test("QoS feature unavailable and journal failure have no writes",delegate{var h=new FakeNetworkHost {Block=true};var s=new FakeNetworkStore();Throws(()=>new NetworkController(h,s,"owner").ApplyQos(Policy()));Assert(h.Writes==0);h.Block=false;s.Fail=true;Throws(()=>new NetworkController(h,s,"owner").ApplyQos(Policy()));Assert(h.Writes==0);});
   Test("QoS interruption rolls back and silent rejection fails",delegate{var h=new FakeNetworkHost {ThrowAfter=true};var s=new FakeNetworkStore();Throws(()=>new NetworkController(h,s,"owner").ApplyQos(Policy()));Assert(h.Qos.Count==0&&s.Value.Qos.Count==0);h.Silent=true;Throws(()=>new NetworkController(h,s,"owner").ApplyQos(Policy()));Assert(h.Qos.Count==0);});
   Test("QoS restore retry preserves backup until policy removed",delegate{var h=new FakeNetworkHost();var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");c.ApplyQos(Policy());h.FailRestore=true;Throws(()=>c.Restore("QoS"));Assert(s.Value.Qos.Count==1);new NetworkController(h,s,"owner").Restore("QoS");Assert(s.Value.Qos.Count==0);});
   Test("QoS external mutation is preserved",delegate{var h=new FakeNetworkHost();var s=new FakeNetworkStore();var p=Policy();new NetworkController(h,s,"owner").ApplyQos(p);h.Qos[p.Name]=new QosPolicy {Name=p.Name,Path=p.Path,BitsPerSecond=9,Dscp=0};Throws(()=>new NetworkController(h,s,"owner").Restore("QoS"));Assert(h.Qos[p.Name].BitsPerSecond==9&&s.Value.Qos.Count==1);});
   Test("QoS altered match fingerprint is preserved even if rate and DSCP match",delegate{var h=new FakeNetworkHost();var s=new FakeNetworkStore();var p=Policy();new NetworkController(h,s,"owner").ApplyQos(p);h.Qos[p.Name]=new QosPolicy {Name=p.Name,Path=p.Path,BitsPerSecond=p.BitsPerSecond,Dscp=p.Dscp,Fingerprint="External match changed"};Throws(()=>new NetworkController(h,s,"owner").Restore("QoS"));Assert(h.Qos.Count==1&&s.Value.Qos.Count==1);});
   Test("Network owner cannot be silently replaced",delegate{var h=Host(4,true);var s=new FakeNetworkStore();new NetworkController(h,s,"owner").ApplyDns(Config(4));Throws(()=>new NetworkController(h,s,"other").Restore("DNS"));Assert(h.ReadDns(Id,4).Same(Config(4)));});
   Test("Corrupt network state and external XML entities block configuration",delegate{Throws(()=>NetworkStateStore.Parse("broken"));Throws(()=>NetworkStateStore.Parse("<!DOCTYPE x [<!ENTITY y SYSTEM 'file:///C:/Windows/win.ini'>]><NetworkState>&y;</NetworkState>"));Throws(()=>NetworkValidation.State(new NetworkState {Version=99}));});
   Test("Network DNS and QoS journals coexist independently",delegate{var h=Host(4,true);var s=new FakeNetworkStore();var c=new NetworkController(h,s,"owner");c.ApplyDns(Config(4));c.ApplyQos(Policy());c.Restore("QoS");Assert(s.Value.Dns.Count==1&&s.Value.Qos.Count==0);c.Restore("DNS");Assert(s.Value.Dns.Count==0);});
   Test("DNS packet parser checks transaction and question before accepting addresses",delegate{byte[] q=DnsProbe.Question("example.com",42);var reply=q.Concat(new byte[]{0xc0,0x0c,0,1,0,1,0,0,0,30,0,4,1,2,3,4}).ToArray();reply[2]=0x81;reply[3]=0x80;reply[7]=1;Assert(DnsProbe.Answer(reply,42,q).Single()=="1.2.3.4");Throws(()=>DnsProbe.Answer(reply,43,q));reply[3]=0x83;Throws(()=>DnsProbe.Answer(reply,42,q));});
   Test("Process endpoint parser handles IPv4 TCP and does not invent UDP remotes",delegate{var b=new byte[28];BitConverter.GetBytes(1).CopyTo(b,0);BitConverter.GetBytes(5).CopyTo(b,4);b[8]=127;b[11]=1;b[12]=0x69;b[13]=0x87;b[16]=1;b[17]=2;b[18]=3;b[19]=4;b[20]=1;b[21]=0xbb;BitConverter.GetBytes(42).CopyTo(b,24);var tcp=GameConnections.Parse(b,true,2).Single();Assert(tcp.ProcessId==42&&tcp.LocalPort==27015&&tcp.RemotePort==443&&tcp.RemoteAddress=="1.2.3.4");var udp=new byte[16];BitConverter.GetBytes(1).CopyTo(udp,0);Assert(GameConnections.Parse(udp,false,2).Single().RemoteAddress==null);Throws(()=>GameConnections.Parse(new byte[]{1,0,0,0},true,23));});
   Test("IPv6 TCP and UDP endpoint layouts preserve scope, port and owner",delegate{var tcp=new byte[60];BitConverter.GetBytes(1).CopyTo(tcp,0);tcp[19]=1;tcp[24]=0x69;tcp[25]=0x87;tcp[43]=1;tcp[48]=1;tcp[49]=0xbb;BitConverter.GetBytes(5).CopyTo(tcp,52);BitConverter.GetBytes(99).CopyTo(tcp,56);var row=GameConnections.Parse(tcp,true,23).Single();Assert(row.LocalAddress=="::1"&&row.RemoteAddress=="::1"&&row.LocalPort==27015&&row.RemotePort==443&&row.ProcessId==99);var udp=new byte[32];BitConverter.GetBytes(1).CopyTo(udp,0);udp[19]=1;udp[24]=0x69;udp[25]=0x87;BitConverter.GetBytes(99).CopyTo(udp,28);var u=GameConnections.Parse(udp,false,23).Single();Assert(u.LocalPort==27015&&u.ProcessId==99&&u.RemoteAddress==null);});
   Test("NextDNS errors, HTTP denial and offline responses never expose API key",delegate{const string key="secret-123456789";foreach(bool offline in new[]{false,true}){var h=new FakeNextHandler {Unavailable=offline,Code=HttpStatusCode.Forbidden};using(var api=new NextDnsClient(key,h))try{api.Profiles(CancellationToken.None).GetAwaiter().GetResult();throw new Exception("Expected error");}catch(IOException e){Assert(!e.Message.Contains(key));}}var failed=new FakeNextHandler {Body="{\"errors\":[{\"code\":\"invalid\"}]}"};using(var api=new NextDnsClient(key,failed))Throws(()=>api.Profiles(CancellationToken.None).GetAwaiter().GetResult());});
   Test("NextDNS allowlist sends authenticated bounded official request",delegate{var h=new FakeNextHandler();using(var api=new NextDnsClient("test-secret-123",h)){api.Change("abc123","allowlist","EXAMPLE.COM",false,CancellationToken.None).GetAwaiter().GetResult();Assert(h.SeenKey=="test-secret-123"&&h.SeenUri=="https://api.nextdns.io/profiles/abc123/allowlist"&&h.SeenBody.Contains("example.com"));Throws(()=>api.Change("bad/id","allowlist","a.com",false,CancellationToken.None).GetAwaiter().GetResult());Throws(()=>api.Request("DELETE","profiles/abc123",null,CancellationToken.None).GetAwaiter().GetResult());}});
   Test("DPAPI token storage contains no plaintext and detects corruption",delegate{Temp(root=>{string path=Path.Combine(root,"key");var store=new ApiKeyStore(path);Throws(()=>store.Save("secret-key\0injected"));store.Save("private-api-key-123");Assert(!Encoding.UTF8.GetString(File.ReadAllBytes(path)).Contains("private-api-key-123")&&store.Load()=="private-api-key-123");File.WriteAllText(path,"corrupted");Throws(()=>store.Load());store.Delete();Assert(!File.Exists(path));});});
   Test("CPU counters subtract idle without double-counting kernel time",delegate{Assert(PerformanceMonitor.CpuDelta(10,20,10,30,60,30)==(double?)(100.0*40/60));Assert(!PerformanceMonitor.CpuDelta(0,0,0,3,1,0).HasValue);});
   Test("Benchmark comparison rejects unequal windows and cannot claim FPS",delegate{var samples=new[]{new PerformanceSample {CpuPercent=40},new PerformanceSample {CpuPercent=50}};var a=new BenchmarkResult {Duration=10,Interval=1000,Samples=samples};var b=new BenchmarkResult {Duration=20,Interval=1000,Samples=samples};Throws(()=>BenchmarkComparison.Compare(a,b));b.Duration=10;Assert(BenchmarkComparison.Compare(a,b).Contains("FPS/1% Low/frametime здесь не измеряются"));});
   Test("Game profiles default to monitoring without network writes",delegate{var profiles=GameProfileManager.Defaults();Assert(profiles[0].ProcessName=="cs2"&&profiles.Length==3);foreach(var profile in profiles)GameProfileManager.Validate(profile);Temp(root=>{string p=Path.Combine(root,"profile.json");GameProfileManager.Save(p,profiles[0]);Assert(GameProfileManager.Load(p).ProcessName=="cs2");File.WriteAllText(p,"{}");Throws(()=>GameProfileManager.Load(p));});});
   Test("NextDNS cancellation and personal data paths remain explicit",delegate{using(var cts=new CancellationTokenSource()){cts.Cancel();using(var api=new NextDnsClient("test-secret-123",new FakeNextHandler()))Throws(()=>api.PrivateData("abc123",true,cts.Token).GetAwaiter().GetResult());}});
   return count;
  }
 }
